let muted=true,audioUnlocked=false,previewCanvas=null,stageBounds=[],lastFrame=0,saveTimer=null;
function freshProject(){return {schema:'resonant-project-v1',version:1,assetSet:'20261009-v1',overrides:{},calibration:{},appearance:{},background:{data:null,name:'',fit:'cover',opacity:1},audio:{},settings:{master:0.7,sfx:0.8,bgm:0.5,outline:1,showAnchors:false,reducedMotion:reduced},battleConfig:{difficulty:'standard',team:['amy','lynae','mornye','denia'],encounter:'normal',level:20,hp_fraction:1,mode:{amy:'tune',denia:'fusion'}}};}
function status(text,error=false){$('assetStatus').textContent=text;$('assetStatus').style.color=error?'#ffb19b':'';}
function toast(text){$('toast').textContent=text;$('toast').classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.add('hidden'),3300);}
function modalOpen(id){pause();$(id).showModal();}
function modalClose(id){$(id).close();schedule();}
function pause(){clearTimeout(timer);timer=null;}
function anyModal(){return !!document.querySelector('dialog[open]');}
function safeAction(fn){try{const r=fn();if(r&&r.catch)r.catch(e=>toast('操作失败：'+e.message));return r;}catch(e){toast('操作失败：'+e.message);}}
async function persistProject(){try{const ok=await store.set('project',project);$('saveStatus').textContent=ok?'素材与设置已存本机 · 不上传':'临时会话 · 请导出项目以防丢失';}catch(e){$('saveStatus').textContent='本地保存失败，请导出项目';status('保存失败：'+e.message,true);}}
