  if(e.event==='shield'){floats.push({id:e.target,text:'弱点 · 盾 −'+e.amount,kind:'shield',start:now+duration*.25,end:now+duration*1.5});}
  if(e.event==='break'){floats.push({id:e.target,text:'BREAK / 破盾',kind:'break',start:now+duration*.4,end:now+duration*1.8});playAudio('break');}
