function render(){if(!battle)return;renderQueue();renderCards();renderActions();renderLogs();renderResult();$('partyCount').textContent=battle.allies.length+' / 4';$('roundNumber').textContent=String(battle.round).padStart(2,'0');$('encounterLabel').textContent=ENC[project.battleConfig.encounter]||'自定义遭遇';$('difficultyBadge').textContent=P.difficulties?.[battle.options.difficulty]?.name||'标准';renderTacticalNotice();$('fieldBadge').textContent=battle.field_until>=battle.round?'定标场生效 · 直伤 +15% / 承伤 −10%':'';}
function statusChips(u){return Object.entries(u.status).map(([k,v])=>`<span class="status-chip ${['fusion','tune','cutline','charge','aim','rend','exposed'].includes(k)?'bad':''}" title="${esc(battle.describeStatus?.(u.id,k)?.description||'')}" tabindex="0">${esc((battle.describeStatus?.(u.id,k)?.name)||LABEL[k]||k)}${v.n?' ×'+v.n:''}${v.amount?' '+v.amount:''}</span>`).join('')+(u.broken_until>=battle.round&&u.broken_until?'<span class="status-chip bad">破盾至 '+u.broken_until+' 轮末</span>':'')+(u.recovery_lock?'<span class="status-chip">恢复锁盾 ≥1</span>':'')+(u.retreated?'<span class="status-chip">已撤离</span>':'');}
