function formEntry(entity,form){const fs=D.forms?.[entity]||{};if(entity==='amy'&&form==='mech')form='mecha';let f=project.appearance[entity]||form;if((entity==='amy'||entity==='denia'))f=form;return fs[f]||fs[form]||fs.normal||Object.values(fs)[0]||null;}
