function scenePositions(W,H){const n=battle.allies.length,m=battle.enemies.length;const ally=battle.allies.map((u,i)=>({id:u.id,x:W*(.61+i*.035),y:H*(.48+i*.11)}));const enemy=battle.enemies.map((u,i)=>{if(m===1)return{id:u.id,x:W*.265,y:H*.85};if(m===2)return{id:u.id,x:W*(.22+i*.19),y:H*(.83-i*.20)};return{id:u.id,x:W*(.12+(i%2)*.25+(i>=2?.04:0)),y:H*(.50+(i%2)*.13+(i>=2?.18:0))};});return [...enemy,...ally];}
