 const iw=rec?.img.naturalWidth||s?.width||s?.naturalWidth||200,ih=rec?.img.naturalHeight||s?.height||s?.naturalHeight||300;const w=Math.max(1,Math.round(iw*ratio)),h=Math.max(1,Math.round(ih*ratio)),left=Math.round(x-w*cal.anchorX),top=Math.round(y-h*cal.anchorY),ol=Math.max(0,Math.round(cal.outline));
