function renderQueue(){const current=battle.current;const portraits=(ids,kind)=>ids.map(id=>{const u=battle.getUnit(id);if(!u||u.hp<=0||u.retreated)return'';const skipped=u.side==='enemy'&&u.broken_until>0&&u.broken_until>=(kind==='next'?battle.round+1:battle.round);const label=u.name+' · '+(kind==='next'?'预计下一轮':'本轮')+' · 速度'+u.speed+(skipped?' · 破盾跳过':'');return `<button class="portrait-token ${u.side} ${skipped?'will-skip':''}" data-portrait-unit="${esc(id)}" aria-label="${esc(label)}" title="${esc(label)}"><canvas aria-hidden="true"></canvas>${skipped?'<span class="skip-label">跳过</span>':u.side==='enemy'?'<span class="token-slot">'+(u.slot+1)+'</span>':''}</button>`;}).join('');$('currentPortrait').innerHTML=current?portraits([current.id],'current'):'';$('queue').innerHTML=portraits(battle.queue,'remaining');const prediction=typeof battle.queuePreview==='function'?battle.queuePreview():null;let next=prediction?.nextPreview?.ids||prediction?.next||prediction?.nextRound;if(Array.isArray(next))next=next.map(v=>typeof v==='string'?v:v.id);else next=battle.living('ally').concat(battle.living('enemy')).sort((a,b)=>b.speed-a.speed||(a.side===b.side?0:a.side==='ally'?-1:1)||a.slot-b.slot).map(u=>u.id);$('nextQueue').innerHTML=battle.result?'':portraits(next,'next');$('queueNote').textContent=busy?'结算中':battle.result?'已结束':'';drawPortraits();}
function drawPortraits(){for(const button of document.querySelectorAll('[data-portrait-unit]')){const u=battle.getUnit(button.dataset.portraitUnit),canvas=button.querySelector('canvas');if(!u||!canvas)continue;const key=slotFor(u,'idle'),s=D.slots[key],rec=getImage(sourceFor(key));if(!s||!rec?.ready)continue;const base=PORTRAIT_RECTS[s.entity+'.'+s.form]||PORTRAIT_RECTS[s.entity]||[0,0,s.width,s.height];const iw=rec.img.naturalWidth,ih=rec.img.naturalHeight,sx=iw/s.width,sy=ih/s.height;const c=calibration(key),custom=project.calibration[key];const rect=custom&&Number.isFinite(custom.portraitW)?[c.portraitX*iw,c.portraitY*ih,c.portraitW*iw,c.portraitH*ih]:[base[0]*sx,base[1]*sy,base[2]*sx,base[3]*sy];canvas.width=64;canvas.height=64;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,64,64);ctx.imageSmoothingEnabled=false;ctx.drawImage(rec.img,...rect,0,0,64,64);}}
function positionOverlays(){if(!battle?.current||!$('commandPanel')||$('commandPanel').classList.contains('hidden'))return;const stage=$('stage'),W=stage.clientWidth||stage.getBoundingClientRect().width,H=stage.clientHeight||stage.getBoundingClientRect().height;if(!W||!H)return;const p=scenePositions(W,H).find(p=>p.id===battle.current.id);if(!p)return;const menu=$('commandPanel'),detail=$('actionDetail'),body=Math.max(24,Math.min(67,H*.135,W*.07))*(D.slots[slotFor(battle.current,'idle')]?.bodyScale||1),mw=menu.offsetWidth||178,mh=Math.min(menu.offsetHeight||244,H-24),dw=Math.min(300,W-24),dhCap=W<620?Math.min(170,H*.35):H-24,dh=Math.min(detail.offsetHeight||245,dhCap);const cal=calibration(slotFor(battle.current,'idle')),ax=p.x+cal.x,ay=p.y+cal.y-cal.ground;let x=ax+body*.55+10,y=ay-body*.95;if(x+mw>W-12)x=ax-body*.6-mw-12;x=Math.max(12,Math.min(W-mw-12,x));y=Math.max(12,Math.min(H-mh-12,y));menu.style.left=Math.round(x)+'px';menu.style.top=Math.round(y)+'px';menu.style.maxHeight=Math.max(160,H-24)+'px';menu.dataset.anchorUnit=battle.current.id;menu.classList.toggle('menu-on-left',x<ax);const candidates=[{x:x-dw-14,y:Math.max(12,y-50)},{x:x,y:y-dh-12},{x:12,y:12},{x:W-dw-12,y:12}];const target=stageBounds.find(b=>b.id===targetId),actor={left:ax-body*.45,top:ay-body,width:body*.9,height:body};function overlap(c,b){return Math.max(0,Math.min(c.x+dw,b.left+b.width)-Math.max(c.x,b.left))*Math.max(0,Math.min(c.y+dh,b.top+b.height)-Math.max(c.y,b.top));}let best=null;for(const c of candidates){c.x=Math.max(12,Math.min(W-dw-12,c.x));c.y=Math.max(12,Math.min(H-dh-12,c.y));c.score=overlap(c,{left:x,top:y,width:mw,height:mh})*5+overlap(c,actor)*3+(target?overlap(c,target)*3:0)+stageBounds.filter(b=>b.id!==battle.current.id&&b.id!==targetId).reduce((sum,b)=>sum+overlap(c,{left:b.x-Math.min(b.width*.22,70),top:b.y-Math.min(b.height*.7,180),width:Math.min(b.width*.44,140),height:Math.min(b.height*.7,180)}),0);if(!best||c.score<best.score)best=c;}detail.style.left=Math.round(best.x)+'px';detail.style.top=Math.round(best.y)+'px';detail.style.width=dw+'px';detail.style.maxHeight=Math.max(110,dhCap)+'px';const arrow=menu.querySelector('.actor-pointer');if(arrow)arrow.style.top=Math.max(15,Math.min(mh-22,ay-body*.55-y))+'px';}
function showHistory(){const entries=window.RELEASE_NOTES?.entries||[];$('historyContent').innerHTML=entries.map(e=>`<h3>${esc(e.version)} · ${esc(e.stage)}</h3><p>${esc(e.summary||'本次反馈与改动进展')}</p>${e.requested?'<ol>'+e.requested.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ol>':''}${e.decisions?'<p>'+e.decisions.map(esc).join('；')+'</p>':''}${e.validation?'<p>验证：'+esc(JSON.stringify(e.validation))+'</p>':''}${e.limitations?'<p>未验/限制：'+e.limitations.map(esc).join('；')+'</p>':''}`).join('');modalOpen('historyDialog');}

function showMigration(text){$('migrationNotice').textContent=text;$('migrationNotice').classList.remove('hidden');}
function renderTacticalNotice(){const charged=battle.living('enemy').map(e=>({e,intent:battle.enemyIntent(e.id)})).filter(x=>x.intent?.committed);const ready=battle.living('ally').filter(a=>a.concerto>=100&&a.concerto_round!==battle.round);const text=charged.map(x=>x.e.name+' · '+x.intent.name+'：'+x.intent.counterplayText).join(' / ')||(ready.length?ready.map(a=>a.name).join('、')+'协奏已满；技能 → 个人协奏，选择接收者':'' );$('tacticalNotice').textContent=text;$('tacticalNotice').classList.toggle('hidden',!text||!!battle.result);}
function wire(){$('assetsBtn').onclick=()=>{modalOpen('assetDialog');renderAssetPanel();};$('setupBtn').onclick=()=>{renderSetup();modalOpen('setupDialog');};$('helpBtn').onclick=()=>modalOpen('helpDialog');$('historyBtn').onclick=showHistory;$('menuBackBtn').onclick=backMenu;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modalClose(b.dataset.close));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',schedule));$('startBtn').onclick=()=>safeAction(startFromSetup);$('difficultySelect').onchange=()=>{$('difficultyDescription').textContent=P.difficulties[$('difficultySelect').value]?.description||'';};$('encounterSelect').onchange=()=>$('customEnemies').classList.toggle('hidden',$('encounterSelect').value!=='custom');$('hpInput').oninput=e=>$('hpOutput').textContent=e.target.value+'%';$('confirmBtn').onclick=()=>{if(!selection||!targetId)return;const key=selection,target=targetId;playAudio('confirm');execute(()=>key.startsWith('__concerto:')?battle.concerto(key.slice(11),target):key==='wait'?battle.wait():battle.act(key,target));};$('cancelBtn').onclick=backMenu;$('stepBtn').onclick=()=>execute(()=>battle.current?.side==='enemy'?battle.stepEnemy():battle.autoAction());$('autoBtn').onclick=()=>{auto=!auto;$('autoBtn').textContent='自动演算：'+(auto?'开':'关');$('autoBtn').setAttribute('aria-pressed',String(auto));schedule();};$('restartBtn').onclick=()=>{if(!window.confirm('重开当前遭遇？本场行动将清空。'))return;startBattle();};$('saveBtn').onclick=()=>saveBattle();$('resumeBtn').onclick=()=>safeAction(async()=>{const data=await store.get('battle')||savedSnapshot;if(!data){toast('还没有可读取的战局');return;}const loaded=BattleEngine.restore(P,data);pause();epoch++;battle=loaded;project.battleConfig=clone(loaded.options);busy=false;auto=false;resetMenu();visuals.clear();floats=[];render();schedule();toast('战局已读取');});$('exportLogBtn').onclick=()=>download('遭遇演算_战斗日志.json',JSON.stringify({parameterVersion:P.schema_version,options:battle.options,summary:battle.summary(),log:battle.log},null,2));$('muteBtn').onclick=toggleMute;$('speedSelect').onchange=schedule;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{assetTab=b.dataset.tab;renderAssetPanel();});$('battleCanvas').onclick=e=>{if(!selection||busy)return;const r=e.target.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const hit=[...stageBounds].reverse().find(b=>x>=b.left&&x<=b.left+b.width&&y>=b.top&&y<=b.top+b.height);if(hit&&battle.availableActions().find(s=>s.key===selection)?.targets.includes(hit.id)){targetId=hit.id;playAudio('select');renderActions();}};document.addEventListener('keydown',e=>{if(anyModal()||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;const menu=$('commandPanel');if(e.key==='Escape'){if(selection||menuCategory!=='root'){backMenu();e.preventDefault();}return;}if(menu.contains(document.activeElement)&&['ArrowDown','ArrowUp'].includes(e.key)){const buttons=[...menu.querySelectorAll('button:not(:disabled)')].filter(b=>!b.closest('.hidden'));const at=buttons.indexOf(document.activeElement),move=e.key==='ArrowDown'?1:-1;buttons[(at+move+buttons.length)%buttons.length]?.focus();e.preventDefault();return;}if(menu.contains(document.activeElement)&&e.key==='ArrowLeft'){backMenu();e.preventDefault();return;}if(e.key==='Enter'&&menu.contains(document.activeElement)&&document.activeElement.tagName==='BUTTON'){e.preventDefault();document.activeElement.click();return;}if(e.key==='ArrowRight'&&document.activeElement.dataset.category){openCategory(document.activeElement.dataset.category);e.preventDefault();return;}if(e.key==='Enter'&&selection&&targetId&&!busy&&!['BUTTON','SUMMARY'].includes(document.activeElement.tagName)){e.preventDefault();$('confirmBtn').click();}});window.addEventListener('beforeunload',()=>{if(battle&&!busy)store.set('battle',battle.snapshot()).catch(()=>{});});}
async function init(){if(!P||!window.BattleEngine)throw new Error('程序文件缺失，请完整解压，确保 parameters.js、engine.js 与 index.html 同目录。');wire();await store.init();try{const saved=await store.get('project');if(saved){const checked=await validateProject(saved);project=checked.project;}}catch(e){toast('上次项目无法恢复，已使用默认设置：'+e.message);}savedSnapshot=await store.get('battle');if(savedSnapshot){try{battle=BattleEngine.restore(P,savedSnapshot);project.battleConfig=clone(battle.options);render();schedule();}catch(e){await store.set('previousVersionBattle',savedSnapshot);showMigration('旧战局未载入：'+e.message+'。素材与校准保留，旧战局已另存本机备份；当前为新规则开场。');startBattle(project.battleConfig,false);}}else startBattle(project.battleConfig);$('saveStatus').textContent=store.available?'素材已保存在本浏览器 · 战局可导出':'浏览器阻止本地缓存 · 请导出项目';$('sceneLabel').textContent=project.background.data?'本地背景 · '+project.background.name:'中性调试舞台 · 等待背景素材';for(const key of Object.keys(D.slots))getImage(sourceFor(key));requestAnimationFrame(drawStage);}
// Read-only UI diagnostics: no credential, network, or gameplay mutation API.
window.BattleLabDiagnostics={getSnapshot:()=>battle?clone(battle.snapshot()):null,getProject:()=>clone(project),getQueue:()=>battle?.queuePreview?.()||null,getOverlayLayout:()=>({stage:{width:$('stage').clientWidth,height:$('stage').clientHeight},menu:{left:$('commandPanel').style.left,top:$('commandPanel').style.top,anchor:$('commandPanel').dataset.anchorUnit},detail:{left:$('actionDetail').style.left,top:$('actionDetail').style.top}}),getState:()=>({menuCategory,inspectedAction,round:battle?.round,current:battle?.currentId,result:clone(battle?.result||null),busy,selected:selection,targetId,assetCount:Object.keys(D.slots).length,overrideCount:Object.keys(project.overrides).length,background:project.background.name,storage:store.available}),validateProject,assets:D};
init().catch(e=>{console.error(e);$('app').innerHTML='<div class="build-error"><h2>程序未能启动</h2><p>'+esc(e.message)+'</p><p>请完整解压后重新打开 index.html。</p></div>';});
